#include <sys/stat.h>
#include <limits.h>
#include <errno.h>

extern int umask_set_from_cmdline;

mode_t set_umask_from_string(const char *optarg) {
    char *endptr;
    long umask_value;
    mode_t new_umask;

    errno = 0;
    umask_value = strtol(optarg, &endptr, 8);

    if (optarg == endptr || *endptr != '\0' || errno != 0 || umask_value < 0 || umask_value > UCHAR_MAX) {
        fprintf(stderr, "Invalid umask value: %s\n", optarg);
        return 0;
