int umask_set_from_cmdline = 0;

mode_t set_umask_from_string(const char *optarg) {
    char *endptr;
    long mask_value = strtol(optarg, &endptr, 10);

    // Check for invalid conversion
    if (optarg[0] == '\0' || *endptr != '\0') {
        fprintf(stderr, "Invalid umask value: %s\n", optarg);
        return 0;
    }

    // Check for out of range values
    if (mask_value < 0 || mask_value > 0777) {
        fprintf(stderr, "Umask value out of range (0-777): %s\n", optarg);
        return 0;
    }

    mode_t new_mask = (mode_t)mask_value;
    umask(new_mask);
    umask_set_from_cmdline = 1;

    return new_mask;
}

